'use strict';
const PS = 'https://portswigger.net/web-security/';
const MDN = 'https://developer.mozilla.org/en-US/docs/';
// Stable topic IDs keep progress shared between the full roadmap and sprint.
const topics = [
  ['http','HTTP & request lifecycle','Pahami perjalanan request dari browser ke server: method, URL, header, body, dan status response.','Bisa membaca satu request dan menjelaskan fungsi setiap bagiannya.','Rekam GET dan POST dari lab lokal.|Bandingkan status 200, 302, 403, dan 404.|Ubah satu parameter lalu jelaskan perubahan response.',MDN+'Web/HTTP'],
  ['html','HTML, JavaScript & DOM','Browser membentuk DOM dari dokumen HTML. JavaScript dapat membaca dan mengubah DOM, termasuk dari input pengguna.','Bisa menelusuri data dari input ke perubahan tampilan.','Buat form HTML sederhana.|Gunakan DevTools untuk membaca DOM dan event listener.|Bedakan nilai di source HTML dan DOM setelah JavaScript berjalan.',MDN+'Web/API/Document_Object_Model'],
  ['cookies','Cookies & sessions','Cookie dikirim sesuai domain, path, dan atributnya. Session biasanya menghubungkan cookie dengan state login di server.','Pahami perbedaan session, cookie, dan token.','Amati Set-Cookie dan Cookie di lab.|Periksa HttpOnly, Secure, dan SameSite.|Bandingkan sesi sebelum dan setelah logout.',PS+'authentication'],
  ['linux','Linux & terminal','Terminal membantu membaca source, mengolah file, dan mengulang request selama CTF.','Nyaman mencari informasi dan mengirim request dari terminal.','Latih navigasi direktori, permission, dan pipe.|Baca response beserta header dengan curl.|Cari keyword di source menggunakan rg.', 'https://overthewire.org/wargames/natas/'],
  ['encoding','URL encoding, Base64 & JSON','Encoding mengubah representasi data. Base64 bukan enkripsi; JSON adalah format serialisasi dengan aturan sintaks sendiri.','Bisa mengenali dan mengurai representasi data umum.','Bandingkan percent encoding dan Base64.|Amati bagaimana server mem-parsing query dan JSON.|Catat perbedaan encoding dan escaping.',MDN+'Glossary/Percent-encoding'],
  ['same-origin','Origin, SOP & CORS','Origin terdiri dari skema, host, dan port. Same-Origin Policy membatasi akses lintas origin; CORS mengatur pengecualian tertentu.','Bisa menjelaskan kapan browser membatasi pembacaan response lintas origin.','Bandingkan dua URL dan tentukan originnya.|Amati request preflight di DevTools.|Bedakan cookie SameSite dari Same-Origin Policy.',PS+'cors'],
  ['backend','Backend & database basics','Kenali routing, input parsing, query database, dan proses rendering pada aplikasi web sederhana.','Bisa mengikuti alur input dari request ke operasi server.','Baca satu aplikasi lab PHP, Flask, atau Express.|Temukan route, middleware, dan query.|Tandai data yang dikendalikan pengguna.',PS+'learning-paths/server-side-vulnerabilities-apprentice'],
  ['devtools','Browser DevTools','Network, Sources, Application, dan Console memberi petunjuk tentang perilaku aplikasi.','Bisa memetakan request, storage, dan script tanpa menebak.','Gunakan Preserve log saat login ke lab.|Periksa localStorage dan cookie.|Cari endpoint yang dipanggil JavaScript.',MDN+'Learn_web_development/Howto/Tools_and_setup/What_are_browser_developer_tools'],
  ['burp','Burp Proxy & Repeater','Proxy membantu mengamati trafik; Repeater mengulang request secara terkontrol agar satu perubahan bisa diuji.','Bisa mengirim request lab ke Repeater dan membandingkan hasil.','Atur browser lab melalui Burp.|Kirim satu request ke Repeater.|Ubah satu field per percobaan dan catat response.', 'https://portswigger.net/burp/documentation/desktop/tools/repeater'],
  ['mapping','Attack surface mapping','Petakan route, parameter, role, dan fitur yang menerima input. Inventaris yang rapi membantu memilih hipotesis.','Punya peta fitur dan input sebelum mulai menguji.','Daftar endpoint dan method pada lab.|Catat input di query, body, header, dan cookie.|Tandai fitur upload, pencarian, login, dan import.',PS+'api-testing'],
  ['source','Source code review','Jika source disediakan, ikuti input menuju operasi sensitif seperti query, render template, filesystem, atau request HTTP.','Bisa menunjukkan hubungan source, sink, dan validasi.','Baca konfigurasi dan entry point lab.|Tandai operasi sensitif beserta inputnya.|Periksa apakah validasi dilakukan sebelum data dipakai.',PS+'information-disclosure'],
  ['disclosure','Information disclosure','Pesan error, komentar, source map, dan file yang terpapar dapat membocorkan detail aplikasi di challenge.','Bisa menemukan informasi relevan dan menghubungkannya dengan hipotesis.','Periksa komentar HTML dan response error.|Baca robots.txt jika tersedia.|Catat teknologi dan path yang diungkap lab.',PS+'information-disclosure'],
  ['python','Python requests & scripting','Script kecil membuat eksperimen berulang lebih konsisten dan membantu menyimpan bukti.','Bisa mengotomasi request ke lab dengan session dan timeout.','Buat session requests untuk lab.|Kirim parameter terstruktur dan periksa status response.|Tambahkan timeout dan simpan hasil yang relevan.', 'https://requests.readthedocs.io/en/latest/user/quickstart/'],
  ['workflow','Hypothesis & writeup','Mulai dari observasi, buat hipotesis, uji perubahan kecil, lalu tulis alasan hasilnya.','Punya catatan yang bisa direproduksi setelah challenge selesai.','Tulis observasi sebelum mencoba input.|Simpan request dan response pembukti.|Rangkum akar masalah, langkah, dan perbaikannya.', 'https://overthewire.org/wargames/natas/'],
  ['sqli','SQL injection','SQL injection muncul ketika input dapat mengubah struktur query. Pelajari konteks query dan bedanya data dengan sintaks.','Bisa mengidentifikasi SQLi di lab dan menjelaskan akar masalahnya.','Selesaikan lab SQLi dasar.|Bandingkan hasil normal dan kondisi uji.|Jelaskan bagaimana parameterized query mencegahnya.',PS+'sql-injection'],
  ['traversal','Path traversal & LFI','Input path yang tidak dibatasi dapat keluar dari direktori yang diharapkan. LFI berkaitan dengan pemuatan file lokal oleh aplikasi.','Bisa membedakan akses file, traversal, dan proses include.','Telusuri fitur pembaca file pada lab.|Amati normalisasi path dan base directory.|Selesaikan lab traversal dasar dan tulis mitigasinya.',PS+'file-path-traversal'],
  ['command','OS command injection','Input yang masuk ke interpreter shell dapat memengaruhi perintah yang dijalankan server.','Bisa menjelaskan batas antara argumen data dan sintaks shell.','Temukan fitur lab yang memanggil proses sistem.|Selesaikan lab command injection dasar.|Bandingkan pemanggilan shell dan API proses dengan argumen terpisah.',PS+'os-command-injection'],
  ['upload','File upload vulnerabilities','Validasi ekstensi, tipe konten, penyimpanan, dan cara file disajikan semuanya memengaruhi keamanan upload.','Bisa menilai alur validasi dan pemrosesan upload di lab.','Petakan langkah upload hingga file diakses.|Bandingkan ekstensi, MIME type, dan konten.|Selesaikan lab upload dan jelaskan penyimpanan yang aman.',PS+'file-upload'],
  ['ssti','Server-side template injection','SSTI terjadi ketika input pengguna diperlakukan sebagai sintaks template, bukan sebagai data yang dirender.','Bisa membedakan SSTI dan refleksi input biasa.','Kenali engine dari source atau petunjuk lab.|Gunakan ekspresi aritmetika sederhana untuk konfirmasi di lab.|Jelaskan pemisahan template dan data.',PS+'server-side-template-injection'],
  ['ssrf','Server-side request forgery','SSRF memungkinkan input memengaruhi request yang dibuat server. Pahami perbedaan request server dan request browser.','Bisa memetakan alur URL input ke HTTP client server.','Temukan fitur fetch URL pada lab.|Amati bagaimana host dan skema divalidasi.|Selesaikan lab SSRF dasar dan catat pembatasan egress.',PS+'ssrf'],
  ['xxe','XXE & XML parsers','Parser XML dengan konfigurasi external entity yang tidak aman dapat mengakses resource di luar dokumen.','Pahami peran parser dan konfigurasi entity.','Baca dokumen XML sederhana.|Identifikasi library parser pada source lab.|Selesaikan lab XXE dasar dan jelaskan penonaktifan entity eksternal.',PS+'xxe'],
  ['xss','Reflected & stored XSS','XSS muncul ketika data yang tidak dipercaya dapat menjadi konten aktif di browser. Konteks HTML, atribut, dan JavaScript berbeda.','Bisa menelusuri input ke konteks output dan memilih encoding yang sesuai.','Bandingkan reflected dan stored XSS pada lab.|Amati konteks tempat input dirender.|Jelaskan context-aware output encoding.',PS+'cross-site-scripting'],
  ['domxss','DOM XSS: sources & sinks','DOM XSS terjadi di sisi browser ketika data yang tidak dipercaya mengalir menuju sink yang memproses HTML atau script.','Bisa mengikuti aliran data melalui JavaScript.','Cari pembacaan location atau pesan pada lab.|Telusuri data ke sink DOM.|Bandingkan textContent dan innerHTML.',PS+'cross-site-scripting/dom-based'],
  ['csrf','Cross-site request forgery','CSRF memanfaatkan kredensial yang otomatis disertakan browser untuk memicu aksi yang tidak dimaksudkan pengguna.','Bisa menjelaskan kondisi CSRF dan fungsi token anti-CSRF.','Petakan aksi yang mengubah state pada lab.|Periksa token dan verifikasi Origin.|Jelaskan peran SameSite dan keterbatasannya.',PS+'csrf'],
  ['cors','CORS misconfiguration','Konfigurasi CORS yang mempercayai origin secara tidak aman dapat memungkinkan pembacaan data lintas origin.','Bisa menilai hubungan allowed origin dan credential.','Amati Access-Control-Allow-Origin pada lab.|Periksa apakah origin direfleksikan.|Selesaikan lab CORS dan tulis kebijakan origin yang sesuai.',PS+'cors'],
  ['clickjacking','Clickjacking & framing','Antarmuka yang bisa ditanam pada frame dapat disalahgunakan untuk mengelabui klik pengguna.','Bisa menjelaskan perlindungan framing pada browser.','Periksa header framing dari lab.|Amati perilaku halaman saat dimuat dalam iframe.|Pelajari CSP frame-ancestors dan X-Frame-Options.',PS+'clickjacking'],
  ['csp','Content Security Policy','CSP membatasi resource dan eksekusi konten sesuai kebijakan. Pahami directive, nonce, dan bagaimana kebijakan diterapkan.','Bisa membaca kebijakan CSP tanpa menganggapnya pengganti encoding.','Baca header CSP dari lab.|Amati pelanggaran kebijakan di Console.|Bedakan kebijakan report-only dan enforcement.',MDN+'Web/HTTP/Guides/CSP'],
  ['postmessage','postMessage & WebSockets','Komunikasi pesan dan koneksi dua arah membawa permukaan input baru. Validasi origin, struktur pesan, dan otorisasi tetap penting.','Bisa memetakan batas kepercayaan pada komunikasi browser.','Telusuri handler message di source lab.|Amati handshake dan frame WebSocket.|Periksa autentikasi dan otorisasi tiap aksi.',PS+'websockets'],
  ['auth','Authentication flaws','Autentikasi membuktikan identitas. Periksa alur login, reset password, MFA, dan session secara utuh.','Bisa memetakan transisi state pada alur autentikasi.','Gambar alur login dan reset password lab.|Periksa invalidasi session setelah perubahan akun.|Selesaikan lab autentikasi dasar.',PS+'authentication'],
  ['idor','IDOR & access control','Mengubah identifier bukan akar masalahnya; akses objek yang tidak diotorisasi adalah masalahnya. Otorisasi harus diperiksa di server.','Bisa membedakan autentikasi dari hak akses objek dan fungsi.','Bandingkan akses dua akun uji pada lab.|Periksa otorisasi untuk membaca dan mengubah objek.|Selesaikan lab akses kontrol horizontal.',PS+'access-control'],
  ['jwt','JWT & session integrity','JWT berisi claim yang ditandatangani. Verifikasi signature, algoritma, expiry, dan konteks penggunaan sangat penting.','Bisa membaca claim tanpa menyamakan decoding dengan verifikasi.','Pisahkan header, payload, dan signature.|Periksa claim exp, iss, dan aud sesuai aplikasi lab.|Selesaikan lab JWT dan jelaskan validasi server.',PS+'jwt'],
  ['logic','Business logic flaws','Aplikasi dapat menjalankan aturan yang keliru meski inputnya valid secara sintaks. Periksa urutan aksi dan asumsi domain.','Bisa mencari state yang bertentangan dengan aturan bisnis lab.','Gambar state diagram checkout atau kupon lab.|Uji urutan aksi yang berbeda.|Tulis invariant yang seharusnya dipertahankan.',PS+'logic-flaws'],
  ['race','Race conditions','Request bersamaan dapat mematahkan asumsi bahwa pemeriksaan dan perubahan state berlangsung sebagai satu operasi.','Bisa menjelaskan check-then-act dan kebutuhan operasi atomik.','Identifikasi resource bersama pada lab.|Bandingkan perilaku request berurutan dan bersamaan.|Pelajari transaksi, lock, dan constraint.',PS+'race-conditions'],
  ['api','REST, GraphQL & API testing','API membutuhkan validasi input dan otorisasi pada objek, properti, dan operasi. Dokumentasi membantu memahami kontraknya.','Bisa memetakan endpoint, field, role, dan method API.','Inventaris endpoint dan skema input lab.|Periksa izin properti yang bisa dibaca atau ditulis.|Bandingkan REST dan GraphQL pada batas otorisasinya.',PS+'api-testing'],
  ['oauth','OAuth & account linking','OAuth melibatkan beberapa pihak dan redirect. Pahami state, redirect URI, authorization code, dan pengikatan akun.','Bisa menggambar alur OAuth dan batas kepercayaan antarpihak.','Gambar alur authorization code dari lab.|Amati validasi redirect URI dan state.|Periksa bagaimana identitas provider diikat ke akun.',PS+'oauth-authentication'],
  ['deserialize','Insecure deserialization','Deserialisasi membentuk kembali objek dari data. Input tidak dipercaya dapat memengaruhi perilaku jika proses ini membuka kemampuan berbahaya.','Bisa mengidentifikasi data serial dan memahami risiko rekonstruksi objek.','Temukan format serialisasi pada lab.|Telusuri data sampai fungsi deserialisasi.|Selesaikan lab dasar dan bandingkan format data sederhana.',PS+'deserialization'],
  ['prototype','Prototype pollution','Di JavaScript, perubahan prototype dapat memengaruhi objek lain. Telusuri cara properti ditulis dan kemudian dibaca.','Bisa menghubungkan source pollution dengan perilaku sink.','Pelajari prototype chain pada contoh lokal.|Baca fungsi merge pada lab.|Selesaikan lab dasar dan catat penggunaan own-property checks.',PS+'prototype-pollution'],
  ['smuggling','HTTP request smuggling','Perbedaan parsing request antar komponen dapat menyebabkan batas request ditafsirkan berbeda. Topik ini butuh pemahaman HTTP yang kuat.','Bisa menjelaskan peran frontend, backend, dan batas pesan HTTP.','Gambar alur reverse proxy dan backend lab.|Baca aturan panjang dan framing request.|Selesaikan lab pengantar dengan panduan Academy.',PS+'request-smuggling'],
  ['cache','Web cache poisoning & deception','Cache menyimpan response berdasarkan key. Ketidaksesuaian key, input, dan aturan cache dapat membuat data atau konten salah disajikan.','Bisa membedakan poisoning dari deception.','Amati header dan perilaku cache di lab.|Identifikasi bagian request yang masuk cache key.|Pelajari cache-control dan pemisahan konten privat.',PS+'web-cache-poisoning'],
  ['nosql','NoSQL injection','Input yang mengubah struktur query NoSQL dapat mengubah makna operasi database. Risiko bergantung pada API dan cara query dirakit.','Bisa membedakan input nilai dan struktur operator pada query.','Baca konstruksi query pada source lab.|Bandingkan tipe string dan objek pada input JSON.|Selesaikan lab NoSQL dasar dan catat validasi skema.',PS+'nosql-injection'],
  ['chaining','Exploit chaining & triage','Dalam CTF, satu temuan sering menjadi pijakan untuk temuan berikutnya. Nilai bukti dan prasyarat sebelum menggabungkan celah.','Bisa menulis rantai temuan dengan dependensi yang jelas.','Daftar temuan beserta kemampuan yang diperoleh.|Susun prasyarat setiap langkah.|Buktikan rantai di lab dan singkirkan asumsi yang belum teruji.',PS+'learning-paths'],
  ['match','CTF practice & final writeup','Latih triase, pembagian waktu, dan dokumentasi dengan challenge yang topiknya belum kamu ketahui.','Bisa menyelesaikan challenge dan menjelaskan penyebabnya secara mandiri.','Kerjakan challenge latihan dengan batas waktu sendiri.|Catat hipotesis gagal dan alasan beralih strategi.|Tulis writeup dari observasi hingga flag, lalu refleksi.', 'https://overthewire.org/wargames/natas/']
].map(([id,title,description,goal,tasks,url])=>({id,title,description,goal,tasks:tasks.split('|'),url}));
const topicById = new Map(topics.map(t=>[t.id,t]));
const chapters = [
  {title:'The web foundations',short:'Fondasi web',groups:[['UNDERSTAND THE WEB',['http','html','cookies','same-origin']],['BUILD YOUR BASE',['linux','encoding','backend']]],milestone:'Bisa membaca request dan mengikuti alur input.'},
  {title:'Observe before you exploit',short:'Tools & observasi',groups:[['YOUR TOOLKIT',['devtools','burp','python']],['READ THE CLUES',['mapping','source','disclosure','workflow']]],milestone:'Punya peta aplikasi dan hipotesis yang bisa diuji.'},
  {title:'Behind the server',short:'Server-side',groups:[['INPUT TO EXECUTION',['sqli','command','ssti']],['FILES & REQUESTS',['traversal','upload','ssrf','xxe']]],milestone:'Pahami bagaimana input melewati batas kepercayaan server.'},
  {title:'Inside the browser',short:'Client-side',groups:[['SCRIPT & RENDERING',['xss','domxss','csp']],['CROSSING ORIGINS',['csrf','cors','clickjacking','postmessage']]],milestone:'Bisa menelusuri data dari input ke perilaku browser.'},
  {title:'Identity, trust & logic',short:'Auth & business logic',groups:[['WHO CAN DO WHAT?',['auth','idor','jwt','oauth']],['BREAK THE ASSUMPTION',['logic','race','api']]],milestone:'Bisa membedakan identitas, izin akses, dan aturan bisnis.'},
  {title:'Beyond the obvious',short:'Advanced & CTF',groups:[['DEEPER PRIMITIVES',['deserialize','prototype','nosql']],['CHAIN IT ALL TOGETHER',['smuggling','cache','chaining','match']]],milestone:'Hubungkan temuan, buktikan, dan tulis cerita di balik flag.'}
];
const sprint=[
  {title:'Week 01 · Read the web',short:'Minggu 1 · Fondasi',groups:[['HARI 1–3 · FONDASI',['http','html','cookies']],['HARI 4–7 · OBSERVASI',['devtools','burp','mapping']]],milestone:'Target: baca satu aplikasi lab dan dokumentasikan request utamanya.'},
  {title:'Week 02 · Find the weakness',short:'Minggu 2 · Celah dasar',groups:[['HARI 8–10 · SERVER',['sqli','traversal','command']],['HARI 11–14 · BROWSER & AKSES',['xss','auth','idor']]],milestone:'Target: satu lab dasar per topik, beserta alasan celahnya.'},
  {title:'Week 03 · Capture the flag',short:'Minggu 3 · Praktik CTF',groups:[['HARI 15–17 · EKSPLORASI',['upload','ssti','ssrf']],['HARI 18–21 · LATIHAN MANDIRI',['source','workflow','match']]],milestone:'Target: challenge mandiri, review hint jika perlu, dan satu writeup lengkap.'}
];
const STORAGE='citlali-web-roadmap-v1';
let state={};let storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))state=saved;}catch{storageOK=false;}
let track='full',activeTopic=null,toastTimer;
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getStatus=id=>['todo','doing','done'].includes(state[id]?.status)?state[id].status:'todo';
const statusIcon=id=>({todo:'◇',doing:'◐',done:'✓'})[getStatus(id)];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Penyimpanan browser tidak tersedia. Ekspor progres agar tidak hilang.');}updateProgress();}
function updateProgress(){const done=topics.filter(t=>getStatus(t.id)==='done').length;const pct=Math.round(done/topics.length*100);$('#percent').innerHTML=pct+'<span>%</span>';$('#progress-fill').style.width=pct+'%';$('#progress-label').textContent=done+' / '+topics.length+' topik dikuasai';$('#mobile-progress').textContent=done+' / '+topics.length+' topik dikuasai';$('.local-tag').innerHTML='<i></i> '+(storageOK?'Tersimpan di browser ini':'Penyimpanan browser tidak tersedia');$('#continue').innerHTML=(done?'Lanjutkan petualangan':'Mulai petualangan')+' <span>↗</span>';}
function render(){
  const data=track==='full'?chapters:sprint;const query=$('#search').value.trim().toLocaleLowerCase('id');const filter=$('#status-filter').value;let shown=0;
  $('#stage-nav').innerHTML=data.map((c,i)=>`<a href="#chapter-${i}"><span>${String(i+1).padStart(2,'0')}</span>${c.short}</a>`).join('');
  $('#track-description').textContent=track==='full'?'6 chapter · 42 topik · dari fondasi sampai kompetisi':'3 minggu · 18 topik inti · saran 1–2 jam per hari';
  $('#roadmap').innerHTML=data.map((c,i)=>{
    const groups=c.groups.map(([name,ids])=>[name,ids.filter(id=>{const t=topicById.get(id);return(filter==='all'||getStatus(id)===filter)&&(!query||(t.title+' '+t.description+' '+c.title+' '+c.short).toLocaleLowerCase('id').includes(query));})]).filter(([,ids])=>ids.length);
    if(!groups.length)return '';
    const ids=c.groups.flatMap(([,ids])=>ids);const count=ids.filter(id=>getStatus(id)==='done').length;
    shown+=groups.reduce((n,[,ids])=>n+ids.length,0);
    return `<section class="stage" id="chapter-${i}" aria-labelledby="heading-${i}"><div class="chapter-head"><div class="chapter-title"><span>${String(i+1).padStart(2,'0')}</span><h3 id="heading-${i}">${c.title}</h3><small>${count}/${ids.length}</small></div></div><div class="groups">${groups.map(([name,ids])=>`<div class="group"><div class="group-label">${name}<span>✧</span></div>${ids.map(id=>`<button class="topic" data-id="${id}" data-status="${getStatus(id)}" aria-label="${escapeHTML(topicById.get(id).title)} — ${{todo:'Belum mulai',doing:'Sedang belajar',done:'Sudah paham'}[getStatus(id)]}"><span>${escapeHTML(topicById.get(id).title)}</span><span class="node-icon" aria-hidden="true">${statusIcon(id)}</span></button>`).join('')}</div>`).join('')}</div><div class="stage-footer"><span>✦</span> ${c.milestone}</div></section>`;
  }).join('')||'<div class="empty">✧ Belum ada topik yang cocok.<p>Coba kata kunci lain atau ubah filter status.</p></div>';
  if(query||filter!=='all')$('#track-description').textContent=shown+' topik sesuai pencarian & filter';
  $('#journey-end').hidden=shown===0;
}
function showTopic(id){
  const t=topicById.get(id);if(!t)return;activeTopic=id;
  const idx=chapters.findIndex(c=>c.groups.some(([,ids])=>ids.includes(id)));
  $('#dialog-chapter').textContent='CHAPTER '+String(idx+1).padStart(2,'0')+' / '+chapters[idx].short.toUpperCase();
  $('#dialog-content').innerHTML=`<h2 id="dialog-title">${escapeHTML(t.title)}</h2><p class="dialog-lead">${escapeHTML(t.description)}</p><div class="detail-label">✦ TUJUAN BELAJAR</div><div class="objective">${escapeHTML(t.goal)}</div><div class="detail-label">COBA DI LAB</div><ol class="detail-tasks">${t.tasks.map(x=>'<li>'+escapeHTML(x)+'</li>').join('')}</ol><a class="resource-link" href="${t.url}" target="_blank" rel="noopener noreferrer"><span>${t.url.includes('portswigger')?'Buka materi & lab di PortSwigger':t.url.includes('mozilla')?'Baca referensi di MDN':t.url.includes('overthewire')?'Latihan di Natas':'Buka dokumentasi'}</span><span>↗</span></a><div class="detail-label">PROGRES BELAJAR</div><div class="status-buttons">${[['todo','◇ Belum mulai'],['doing','◐ Dipelajari'],['done','✓ Sudah paham']].map(([s,label])=>`<button data-state="${s}" aria-pressed="${getStatus(id)===s}" class="${getStatus(id)===s?'active':''}">${label}</button>`).join('')}</div><label class="detail-label" for="topic-note" style="display:block">CATATAN PRIBADI</label><textarea id="topic-note" maxlength="10000" placeholder="Hipotesis, hal yang baru dipahami, atau nama lab yang sudah selesai…"></textarea><span class="note-hint">Disimpan otomatis di browser ini · Ekspor progres untuk membuat cadangan.</span><div class="dialog-actions"><button class="secondary" data-close>Selesai mencatat</button></div>`;
  $('#topic-note').value=typeof state[id]?.note==='string'?state[id].note:'';
  $('#topic-dialog').showModal();
}
$('#roadmap').addEventListener('click',e=>{const topic=e.target.closest('[data-id]');if(topic)showTopic(topic.dataset.id);});
$('#dialog-content').addEventListener('click',e=>{const b=e.target.closest('[data-state]');if(!b||!activeTopic)return;state[activeTopic]={...state[activeTopic],status:b.dataset.state};save();render();document.querySelectorAll('[data-state]').forEach(x=>{const chosen=x.dataset.state===b.dataset.state;x.classList.toggle('active',chosen);x.setAttribute('aria-pressed',String(chosen));});});
$('#dialog-content').addEventListener('input',e=>{if(e.target.id==='topic-note'&&activeTopic){state[activeTopic]={...state[activeTopic],note:e.target.value};save();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-close]');if(b)b.closest('dialog').close();});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>{track=b.dataset.track;document.querySelectorAll('[data-track]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('#roadmap').setAttribute('aria-labelledby',b.id);render();}));
$('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const b=Array.from(document.querySelectorAll('[data-track]'));const next=e.key==='Home'?b[0]:e.key==='End'?b[1]:b.find(x=>x!==document.activeElement);next.focus();next.click();});
$('#search').addEventListener('input',render);$('#status-filter').addEventListener('change',render);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus();}});
$('#resources').addEventListener('click',()=>$('#resource-dialog').showModal());
$('#print').addEventListener('click',()=>window.print());
$('#reset').addEventListener('click',()=>$('#reset-dialog').showModal());
$('#confirm-reset').addEventListener('click',()=>{state={};save();render();$('#reset-dialog').close();toast('Progres direset. Petualangan baru dimulai. ✧');});
$('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({app:'citlali-web-roadmap',version:1,exportedAt:new Date().toISOString(),topics:topics.map(t=>({id:t.id,title:t.title,status:getStatus(t.id),note:state[t.id]?.note||''}))},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='citlali-web-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progres dan catatan berhasil diekspor.');});
$('#mobile-export').addEventListener('click',()=>$('#export').click());
updateProgress();render();
